// TitanServer is the server API for Titan service.
// All implementations must embed UnimplementedTitanServer
// for forward compatibility.
//
// ----------------------
// Titan gRPC Service
// ----------------------
type TitanServer interface {
	Ping(context.Context, *PingReq) (*PingResp, error)
	// 集成凭证
	ListIntegrations(context.Context, *ListIntegrationsReq) (*ListIntegrationsResp, error)
	CreateIntegration(context.Context, *CreateIntegrationReq) (*CreateIntegrationResp, error)
	UpdateIntegration(context.Context, *UpdateIntegrationReq) (*CommonResp, error)
	DeleteIntegration(context.Context, *DeleteIntegrationReq) (*CommonResp, error)
	TestIntegration(context.Context, *TestIntegrationReq) (*TestIntegrationResp, error)
	// K8s 集群
	ListClusters(context.Context, *ListClustersReq) (*ListClustersResp, error)
	CreateCluster(context.Context, *CreateClusterReq) (*CreateClusterResp, error)
	UpdateCluster(context.Context, *UpdateClusterReq) (*CommonResp, error)
	DeleteCluster(context.Context, *DeleteClusterReq) (*CommonResp, error)
	TestCluster(context.Context, *TestClusterReq) (*TestClusterResp, error)
	ListNamespaces(context.Context, *ListNamespacesReq) (*ListNamespacesResp, error)
	// 流水线定义
	ListPipelines(context.Context, *ListPipelinesReq) (*ListPipelinesResp, error)
	GetPipeline(context.Context, *GetPipelineReq) (*PipelineDetailResp, error)
	CreatePipeline(context.Context, *CreatePipelineReq) (*CreatePipelineResp, error)
	UpdatePipeline(context.Context, *UpdatePipelineReq) (*CommonResp, error)
	DeletePipeline(context.Context, *DeletePipelineReq) (*CommonResp, error)
	// 执行与步骤控制
	TriggerPipeline(context.Context, *TriggerPipelineReq) (*TriggerPipelineResp, error)
	ListExecutions(context.Context, *ListExecutionsReq) (*ListExecutionsResp, error)
	GetExecutionDetail(context.Context, *GetExecutionDetailReq) (*ExecutionDetailResp, error)
	GetStepLog(context.Context, *GetStepLogReq) (*GetStepLogResp, error)
	ApproveStep(context.Context, *ApproveStepReq) (*CommonResp, error)
	CancelExecution(context.Context, *CancelExecutionReq) (*CommonResp, error)
	// ----------------------
	// Zadig CI/CD 演进服务
	// ----------------------
	// 1. 项目 (Project)
	ListProjects(context.Context, *ListProjectsReq) (*ListProjectsResp, error)
	GetProject(context.Context, *GetProjectReq) (*ProjectDetailResp, error)
	CreateProject(context.Context, *CreateProjectReq) (*CreateProjectResp, error)
	UpdateProject(context.Context, *UpdateProjectReq) (*CommonResp, error)
	DeleteProject(context.Context, *DeleteProjectReq) (*CommonResp, error)
	// 2. 应用 (Application)
	ListApps(context.Context, *ListAppsReq) (*ListAppsResp, error)
	GetApp(context.Context, *GetAppReq) (*AppDetailResp, error)
	CreateApp(context.Context, *CreateAppReq) (*CreateAppResp, error)
	UpdateApp(context.Context, *UpdateAppReq) (*CommonResp, error)
	DeleteApp(context.Context, *DeleteAppReq) (*CommonResp, error)
	// 3. 环境 (Environment)
	ListEnvs(context.Context, *ListEnvsReq) (*ListEnvsResp, error)
	GetEnv(context.Context, *GetEnvReq) (*EnvDetailResp, error)
	CreateEnv(context.Context, *CreateEnvReq) (*CreateEnvResp, error)
	UpdateEnv(context.Context, *UpdateEnvReq) (*CommonResp, error)
	DeleteEnv(context.Context, *DeleteEnvReq) (*CommonResp, error)
	GetEnvLiveDetail(context.Context, *GetEnvLiveDetailReq) (*GetEnvLiveDetailResp, error)
	// 4. 制品 (Artifact)
	ListArtifacts(context.Context, *ListArtifactsReq) (*ListArtifactsResp, error)
	CreateArtifact(context.Context, *CreateArtifactReq) (*CreateArtifactResp, error)
	DeployArtifact(context.Context, *DeployArtifactReq) (*CommonResp, error)
	mustEmbedUnimplementedTitanServer()
}

